  !haveNonExpiringSigningKey &&
  mostFutureSigExpiryTime &&
  (!keyObj.expiryTime || mostFutureSigExpiryTime < keyObj.expiryTime)
) {
  effectiveSigningExpiryTime = mostFutureSigExpiryTime;
  effectiveSigningExpiry = mostFutureSigExpiry;
}

